<script lang="ts">
 import {untrack} from 'svelte';
 import {enhance} from '$app/forms';
 import {toast} from 'svelte-sonner';
 import {ArrowUpRight,Plus,Save,LogOut,FolderOpen,Mail,UserRound,Image,Upload,Check,Archive,Eye,Pencil,ExternalLink} from '@lucide/svelte';
 import {Button} from '#lib/components/ui/button/index.js';
 import {Input} from '#lib/components/ui/input/index.js';
 import {Textarea} from '#lib/components/ui/textarea/index.js';
 import {Badge} from '#lib/components/ui/badge/index.js';
 import * as Card from '#lib/components/ui/card/index.js';
 import * as Tabs from '#lib/components/ui/tabs/index.js';
 import * as Dialog from '#lib/components/ui/dialog/index.js';
 import type {Doc} from '../../../convex/_generated/dataModel';
 let {data,form}=$props();
 type Draft={id?:string;title:string;slug:string;summary:string;body:string;category:string;stack:string;image:string;imageId:string;url:string;published:boolean;order:number};
 let tab=$state('overview');let editorOpen=$state(false);let editing=$state<Draft>({title:'',slug:'',summary:'',body:'',category:'Web development',stack:'',image:'',imageId:'',url:'',published:false,order:0});
 let saving=$state(false);let uploading=$state(false);let resumeId=$state(untrack(()=>data.profile?.resumeId??''));
 const published=$derived(data.projects.filter((p:Doc<'projects'>)=>p.published).length);
 const unread=$derived(data.inbox.page.filter((m:Doc<'messages'>)=>m.status==='new').length);
 function edit(project?:Doc<'projects'>){editing=project?{...project,id:project._id,stack:project.stack.join(', '),imageId:project.imageId??''}:{title:'',slug:'',summary:'',body:'',category:'Web development',stack:'',image:'',imageId:'',url:'',published:false,order:data.projects.length};editorOpen=true;}
 function enhanced(){saving=true;return async({result,update}:any)=>{await update({reset:false});saving=false;if(result.type==='success'&&result.data?.success){toast.success(result.data.success);if(result.data.success==='Project saved.')editorOpen=false;}else if(result.data?.error)toast.error(result.data.error);};}
 function uploadEnhanced(){uploading=true;return async({result,update}:any)=>{await update({reset:false});uploading=false;if(result.type==='success'&&result.data?.storageId){if(result.data.uploadTarget==='resume')resumeId=result.data.storageId;else editing.imageId=result.data.storageId;toast.success('Uploaded. Save changes to attach the file.');}else toast.error(result.data?.error??'Upload failed.');};}
</script>
<svelte:head><title>Portfolio Studio — Dashboard</title><meta name="robots" content="noindex,nofollow"/></svelte:head>
<div class="dashboard">
 <aside class="dashboard-sidebar"><a class="studio-brand" href="/dashboard"><span>Y<span class="accent-text">.</span></span><div>Portfolio<span>STUDIO</span></div></a><div class="sidebar-bottom"><span class="status-dot available"></span> Connected to Convex</div></aside>
 <div class="dashboard-body"><header class="dashboard-header"><div><span class="eyebrow">YOUR CREATIVE SPACE</span><h1>Portfolio studio<span class="accent-text">.</span></h1></div><div class="dashboard-header-actions"><Button href="/" target="_blank" variant="outline">View site <ArrowUpRight size={16}/></Button><form method="POST" action="/logout"><Button type="submit" variant="ghost" size="icon" aria-label="Sign out"><LogOut size={19}/></Button></form></div></header>
 <Tabs.Root bind:value={tab} class="dashboard-tabs"><Tabs.List class="dashboard-tab-list"><Tabs.Trigger value="overview">Overview</Tabs.Trigger><Tabs.Trigger value="profile">Profile</Tabs.Trigger><Tabs.Trigger value="projects">Projects <span class="tab-count">{data.projects.length}</span></Tabs.Trigger><Tabs.Trigger value="inbox">Inbox {#if unread}<span class="tab-count">{unread}</span>{/if}</Tabs.Trigger></Tabs.List>
 <Tabs.Content value="overview"><div class="dashboard-welcome"><div><span class="eyebrow">WELCOME BACK</span><h2>A home for your best work.</h2><p>Keep your story current and your next opportunity close.</p></div><Button onclick={()=>{tab='projects';edit();}} class="pill-action"><Plus size={18}/> Add a project</Button></div><div class="stats-grid"><Card.Root><Card.Header><Card.Description>Published projects</Card.Description><FolderOpen size={20}/></Card.Header><Card.Content><strong class="stat-number">{published}</strong><span>out of {data.projects.length} projects</span></Card.Content></Card.Root><Card.Root><Card.Header><Card.Description>Draft projects</Card.Description><Pencil size={20}/></Card.Header><Card.Content><strong class="stat-number">{data.projects.length-published}</strong><span>only visible in your studio</span></Card.Content></Card.Root><Card.Root><Card.Header><Card.Description>New messages</Card.Description><Mail size={20}/></Card.Header><Card.Content><strong class="stat-number">{unread}</strong><span>in the latest {data.inbox.page.length} messages</span></Card.Content></Card.Root></div><div class="dashboard-section-heading"><h2>Selected work</h2><Button variant="ghost" onclick={()=>tab='projects'}>Manage projects <ArrowUpRight size={17}/></Button></div><div class="dashboard-project-grid">{#each data.projects.slice(0,3) as project}<button class="dashboard-project-preview" onclick={()=>{tab='projects';edit(project);}}><div class="dashboard-project-image">{#if project.image}<img src={project.image} alt={project.title}/>{:else}<Image size={32}/>{/if}</div><div><h3>{project.title}</h3><Badge variant={project.published?'default':'secondary'}>{project.published?'Published':'Draft'}</Badge></div></button>{/each}{#if !data.projects.length}<p class="body-copy">Your next project starts here. Add your first one.</p>{/if}</div></Tabs.Content>
 <Tabs.Content value="profile"><div class="dashboard-section-heading"><div><h2>Your story</h2><p>Make the introduction feel like you.</p></div></div>
 <form method="POST" action="?/profile" use:enhance={enhanced} class="editor-form profile-editor"><div class="form-grid"><div class="field"><label for="profile-name">Name</label><Input id="profile-name" name="name" value={data.profile?.name??''} required maxlength={100}/></div><div class="field"><label for="profile-role">Role</label><Input id="profile-role" name="role" value={data.profile?.role??''} required maxlength={150}/></div></div><div class="field"><label for="profile-bio">A short introduction</label><Textarea id="profile-bio" name="bio" value={data.profile?.bio??''} rows={3} maxlength={3000}/></div><div class="field"><label for="profile-journey">Your journey</label><Textarea id="profile-journey" name="journey" value={data.profile?.journey??''} rows={5} maxlength={6000}/></div><div class="form-grid"><div class="field"><label for="profile-experience">Years of experience</label><Input id="profile-experience" name="experience" value={data.profile?.experience??''} maxlength={15}/></div><div class="field"><label for="profile-email">Public contact email</label><Input id="profile-email" name="email" type="email" value={data.profile?.email??''}/></div><div class="field"><label for="profile-github">GitHub URL</label><Input id="profile-github" name="github" type="url" value={data.profile?.github??''}/></div><div class="field"><label for="profile-linkedin">LinkedIn URL</label><Input id="profile-linkedin" name="linkedin" type="url" value={data.profile?.linkedin??''}/></div></div><div class="field"><label for="profile-skills">Skills</label><Input id="profile-skills" name="skills" value={data.profile?.skills.join(', ')??''}/><p class="field-help">Separate each skill with a comma.</p></div><input type="hidden" name="resumeId" value={resumeId}/><label class="check-field"><input type="checkbox" name="available" checked={data.profile?.available}/> Open to new opportunities</label><div class="form-actions"><Button type="submit" class="pill-action" disabled={saving}><Save size={17}/>{saving?'Saving…':'Save profile'}</Button><span>Changes appear on your site immediately.</span></div></form>
 <div class="upload-panel"><h3>Resume</h3><p class="body-copy">Upload a PDF, then save your profile to make it downloadable.</p><form method="POST" action="?/upload" enctype="multipart/form-data" use:enhance={uploadEnhanced}><input type="hidden" name="target" value="resume"/><label class="sr-only" for="resume-file">Resume PDF</label><Input id="resume-file" type="file" name="file" accept="application/pdf" required/><Button type="submit" variant="outline" disabled={uploading}><Upload size={16}/> {uploading?'Uploading…':'Upload PDF'}</Button></form>{#if resumeId}<p class="field-help">A resume is attached. Save your profile after changing it.</p><Button variant="ghost" onclick={()=>resumeId=''}>Remove attachment</Button>{/if}</div></Tabs.Content>
 <Tabs.Content value="projects"><div class="dashboard-section-heading"><div><h2>Your projects</h2><p>Publish the work you’re proud of. Keep the rest in draft.</p></div><Button onclick={()=>edit()}><Plus size={18}/> New project</Button></div><div class="project-table">{#each data.projects as project}<div class="project-row"><div class="project-row-icon"><FolderOpen size={21}/></div><div class="project-row-title"><h3>{project.title}</h3><p>/{project.slug}</p></div><Badge variant={project.published?'default':'secondary'}>{project.published?'Published':'Draft'}</Badge><Button variant="ghost" onclick={()=>edit(project)} aria-label={`Edit ${project.title}`}><Pencil size={16}/><span>Edit</span></Button></div>{/each}{#if !data.projects.length}<div class="empty-state"><FolderOpen size={34}/><h3>No projects yet.</h3><p>Add your first project to start telling its story.</p></div>{/if}</div></Tabs.Content>
 <Tabs.Content value="inbox"><div class="dashboard-section-heading"><div><h2>Good conversations start here.</h2><p>Messages from your portfolio contact form.</p></div></div><div class="inbox-list">{#each data.inbox.page as message}<Card.Root class="inbox-message"><Card.Header><div><h3>{message.name}</h3><a href={`mailto:${message.email}`} class="muted-link">{message.email}</a></div><Badge variant={message.status==='new'?'default':'secondary'}>{message.status}</Badge></Card.Header><Card.Content><p class="message-text">{message.message}</p><div class="message-footer"><time datetime={new Date(message._creationTime).toISOString()}>{new Date(message._creationTime).toLocaleDateString('en-US',{dateStyle:'medium'})}</time><form method="POST" action="?/message" use:enhance={enhanced}><input type="hidden" name="id" value={message._id}/><Button type="submit" name="status" value={message.status==='read'?'new':'read'} variant="ghost"><Check size={16}/>{message.status==='read'?'Mark new':'Mark read'}</Button><Button type="submit" name="status" value={message.status==='archived'?'new':'archived'} variant="ghost"><Archive size={16}/>{message.status==='archived'?'Restore':'Archive'}</Button></form></div></Card.Content></Card.Root>{/each}{#if !data.inbox.page.length}<div class="empty-state"><Mail size={36}/><h3>A little quiet, for now.</h3><p>When someone reaches out, their message will appear here.</p></div>{/if}</div>{#if !data.inbox.isDone}<Button href={`/dashboard?cursor=${encodeURIComponent(data.inbox.continueCursor)}`} variant="outline">Older messages</Button>{/if}{#if data.inbox.continueCursor&&data.inbox.page.length===0}<Button href="/dashboard">Latest messages</Button>{/if}</Tabs.Content>
 </Tabs.Root><footer class="dashboard-footer">Portfolio Studio <span>Signed in as {data.viewer.email}</span></footer>
 </div>
</div>
<Dialog.Root bind:open={editorOpen}><Dialog.Content class="project-editor-dialog"><Dialog.Header><Dialog.Title>{editing.id?'Edit project':'A new project'}</Dialog.Title><Dialog.Description>Tell the story behind the work.</Dialog.Description></Dialog.Header>
 <form method="POST" action="?/project" use:enhance={enhanced} class="editor-form"><input type="hidden" name="id" value={editing.id??''}/><div class="form-grid"><div class="field"><label for="project-title">Project name</label><Input id="project-title" name="title" bind:value={editing.title} required maxlength={150}/></div><div class="field"><label for="project-slug">URL slug</label><Input id="project-slug" name="slug" bind:value={editing.slug} pattern="[a-z0-9]+(-[a-z0-9]+)*" required placeholder="my-project"/></div></div><div class="field"><label for="project-summary">Short description</label><Textarea id="project-summary" name="summary" bind:value={editing.summary} required maxlength={600} rows={2}/></div><div class="field"><label for="project-body">Case study</label><Textarea id="project-body" name="body" bind:value={editing.body} rows={6} maxlength={20000}/></div><div class="form-grid"><div class="field"><label for="project-category">Category</label><Input id="project-category" name="category" bind:value={editing.category} required/></div><div class="field"><label for="project-order">Display order</label><Input id="project-order" name="order" type="number" bind:value={editing.order} required/></div></div><div class="field"><label for="project-stack">Technologies (comma separated)</label><Input id="project-stack" name="stack" bind:value={editing.stack}/></div><div class="field"><label for="project-url">Live project URL (optional)</label><Input id="project-url" name="url" type="url" bind:value={editing.url} placeholder="https://…"/></div><div class="field"><label for="project-image">Image path or HTTPS URL</label><Input id="project-image" name="image" bind:value={editing.image} placeholder="/images/project.png"/><p class="field-help">Or upload an image below. Uploaded images take priority.</p></div><input type="hidden" name="imageId" value={editing.imageId}/>{#if editing.imageId}<div class="upload-attached"><Check size={15}/> Uploaded image attached <Button variant="ghost" size="sm" onclick={()=>editing.imageId=''}>Remove</Button></div>{/if}<label class="check-field"><input type="checkbox" name="published" bind:checked={editing.published}/> Publish on portfolio</label><div class="form-actions"><Button type="submit" disabled={saving}><Save size={17}/>{saving?'Saving…':'Save project'}</Button><Button variant="ghost" onclick={()=>editorOpen=false}>Cancel</Button></div></form>
 <form method="POST" action="?/upload" enctype="multipart/form-data" use:enhance={uploadEnhanced} class="project-upload"><input type="hidden" name="target" value="project"/><label for="project-file">Project image</label><Input id="project-file" name="file" type="file" accept="image/png,image/jpeg,image/webp" required/><Button type="submit" variant="outline" disabled={uploading}><Upload size={16}/>{uploading?'Uploading…':'Upload image'}</Button></form>
 </Dialog.Content></Dialog.Root>
